#define _POSIX_C_SOURCE 200809L
#include "cvc_snapshot.h"
#include "cvc_object.h"
#include "cvc_glob.h"
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <dirent.h>

void cvc_snapshot_init(CvcSnapshot*s){s->v=NULL;s->n=s->cap=0;s->ignored=0;}
void cvc_snapshot_free(CvcSnapshot*s){for(size_t i=0;i<s->n;i++)free(s->v[i].path);free(s->v);cvc_snapshot_init(s);}
int cvc_snapshot_add(CvcSnapshot*s,const char*path,uint8_t type,const uint8_t oid[32]){if(type!=1&&type!=2)return -1;if(s->n==s->cap){s->cap=s->cap?s->cap*2:64;s->v=cvc_xrealloc(s->v,s->cap*sizeof(*s->v));}s->v[s->n].path=cvc_xstrdup(path);s->v[s->n].type=type;memcpy(s->v[s->n].oid,oid,32);s->n++;return 0;}
static int cmp_entry(const void*a,const void*b){const unsigned char*x=(const unsigned char*)((const CvcSnapEntry*)a)->path,*y=(const unsigned char*)((const CvcSnapEntry*)b)->path;while(*x&&*y){if(*x!=*y)return *x<*y?-1:1;x++;y++;}return *x?1:*y?-1:0;}
void cvc_snapshot_sort(CvcSnapshot *s){
    if(s->n>1)qsort(s->v,s->n,sizeof(*s->v),cmp_entry);
}
ssize_t cvc_snapshot_find(const CvcSnapshot*s,const char*p){size_t lo=0,hi=s->n;while(lo<hi){size_t m=lo+(hi-lo)/2;int c=strcmp(s->v[m].path,p);if(!c)return (ssize_t)m;if(c<0)lo=m+1;else hi=m;}return -1;}
int cvc_snapshot_equal(const CvcSnapshot*a,const CvcSnapshot*b){if(a->n!=b->n)return 0;for(size_t i=0;i<a->n;i++)if(strcmp(a->v[i].path,b->v[i].path)||a->v[i].type!=b->v[i].type||memcmp(a->v[i].oid,b->v[i].oid,32))return 0;return 1;}

static int read_symlink_bytes(const char*path,CvcBuf*b){cvc_buf_init(b);size_t cap=128;for(;;){b->data=cvc_xrealloc(b->data,cap);ssize_t n=readlink(path,(char*)b->data,cap);if(n<0){cvc_buf_free(b);return -1;}if((size_t)n<cap){b->len=(size_t)n;b->cap=cap;return 0;}if(cap>SIZE_MAX/2){cvc_buf_free(b);errno=EOVERFLOW;return -1;}cap*=2;}}
static int dir_has_real_cvc(const char*abs){char*q=cvc_path_join(abs,".cvc");struct stat st;int yes=lstat(q,&st)==0&&S_ISDIR(st.st_mode);free(q);return yes;}
static int scan_dir(const char*root,const char*cvc,const CvcConfig*cfg,int store,const char*rel,CvcSnapshot*out){char*abs=rel[0]?cvc_path_join(root,rel):cvc_xstrdup(root);DIR*d=opendir(abs);if(!d){int e=errno;free(abs);return cvc_errorf("cannot open directory %s: %s",rel[0]?rel:".",strerror(e));}struct dirent*de;int rc=0;while((de=readdir(d))){if(!strcmp(de->d_name,".")||!strcmp(de->d_name,".."))continue;if(!rel[0]&&!strcmp(de->d_name,".cvc"))continue;size_t nl=strlen(de->d_name);if(!cvc_name_component_valid((const unsigned char*)de->d_name,nl)){cvc_warnf("ignoring unsupported filename in %s",rel[0]?rel:".");out->ignored++;continue;}char*rp=rel[0]?cvc_path_join(rel,de->d_name):cvc_xstrdup(de->d_name);char*ap=cvc_path_join(root,rp);struct stat st;if(lstat(ap,&st)<0){cvc_warnf("cannot inspect %s: %s",rp,strerror(errno));out->ignored++;free(rp);free(ap);continue;}if(S_ISDIR(st.st_mode)){if(dir_has_real_cvc(ap)){out->ignored++;free(rp);free(ap);continue;}if(scan_dir(root,cvc,cfg,store,rp,out)<0){free(rp);free(ap);rc=-1;break;}free(rp);free(ap);continue;}if(S_ISREG(st.st_mode)){if((uint64_t)st.st_size>CVC_TEXT_MAX){out->ignored++;free(rp);free(ap);continue;}int fd=open(ap,O_RDONLY|O_CLOEXEC|O_NOFOLLOW);if(fd<0){cvc_warnf("cannot open %s: %s",rp,strerror(errno));out->ignored++;free(rp);free(ap);continue;}struct stat fs;if(fstat(fd,&fs)<0||!S_ISREG(fs.st_mode)||fs.st_size!=st.st_size){close(fd);cvc_warnf("file changed while scanning: %s",rp);out->ignored++;free(rp);free(ap);continue;}unsigned char probe[CVC_PROBE_MAX];size_t want=(size_t)fs.st_size<CVC_PROBE_MAX?(size_t)fs.st_size:CVC_PROBE_MAX;size_t got=0;while(got<want){ssize_t z=read(fd,probe+got,want-got);if(z<0&&errno==EINTR)continue;if(z<=0){rc=-1;break;}got+=(size_t)z;}if(rc<0){close(fd);free(rp);free(ap);break;}if(memchr(probe,0,want)){close(fd);out->ignored++;free(rp);free(ap);continue;}if(!cvc_patterns_select(&cfg->tracking_include,&cfg->tracking_exclude,rp)){close(fd);out->ignored++;free(rp);free(ap);continue;}if(lseek(fd,0,SEEK_SET)<0){rc=cvc_errorf("seek failed for %s",rp);close(fd);free(rp);free(ap);break;}CvcBuf b;cvc_buf_init(&b);cvc_buf_reserve(&b,(size_t)fs.st_size);unsigned char tmp[32768];for(;;){ssize_t z=read(fd,tmp,sizeof(tmp));if(z<0&&errno==EINTR)continue;if(z<0){rc=cvc_errorf("read failed for %s",rp);break;}if(!z)break;cvc_buf_append(&b,tmp,(size_t)z);}int ce=close(fd);if(rc<0||ce<0){if(rc==0)rc=cvc_errorf("close failed for %s",rp);cvc_buf_free(&b);free(rp);free(ap);break;}uint8_t id[32];if(store){if(cvc_object_store(cvc,CVC_OBJ_BLOB,b.data,b.len,id)<0){cvc_buf_free(&b);free(rp);free(ap);rc=-1;break;}}else cvc_object_oid(CVC_OBJ_BLOB,b.data,b.len,id);cvc_snapshot_add(out,rp,1,id);cvc_buf_free(&b);free(rp);free(ap);continue;}if(S_ISLNK(st.st_mode)){CvcBuf b;if(read_symlink_bytes(ap,&b)<0){cvc_warnf("cannot read symlink %s",rp);out->ignored++;free(rp);free(ap);continue;}if(!cvc_patterns_select(&cfg->tracking_include,&cfg->tracking_exclude,rp)){out->ignored++;cvc_buf_free(&b);free(rp);free(ap);continue;}uint8_t id[32];if(store){if(cvc_object_store(cvc,CVC_OBJ_SYMLINK,b.data,b.len,id)<0){cvc_buf_free(&b);free(rp);free(ap);rc=-1;break;}}else cvc_object_oid(CVC_OBJ_SYMLINK,b.data,b.len,id);cvc_snapshot_add(out,rp,2,id);cvc_buf_free(&b);free(rp);free(ap);continue;}out->ignored++;free(rp);free(ap);}int e=errno;if(closedir(d)<0&&rc==0){rc=cvc_errorf("close directory failed");e=errno;}free(abs);errno=e;return rc;}
int cvc_snapshot_scan(const char*root,const char*cvc,const CvcConfig*cfg,int store,CvcSnapshot*out){cvc_snapshot_init(out);if(scan_dir(root,cvc,cfg,store,"",out)<0){cvc_snapshot_free(out);return -1;}cvc_snapshot_sort(out);return 0;}

static int load_tree_rec(const char*cvc,const uint8_t oid[32],const char*prefix,int root,CvcSnapshot*out){CvcObjType t;CvcBuf p;if(cvc_object_read(cvc,oid,&t,&p)<0)return -1;if(t!=CVC_OBJ_TREE){cvc_buf_free(&p);return cvc_errorf("tree reference points to wrong object type");}CvcTree tr;if(cvc_tree_parse(p.data,p.len,&tr,root)<0){cvc_buf_free(&p);return cvc_errorf("malformed/noncanonical tree");}cvc_buf_free(&p);if(!root&&tr.n==0){cvc_tree_free(&tr);return cvc_errorf("non-root empty subtree is noncanonical");}for(size_t i=0;i<tr.n;i++){char*path=prefix[0]?cvc_path_join(prefix,tr.v[i].name):cvc_xstrdup(tr.v[i].name);if(tr.v[i].type==3){if(load_tree_rec(cvc,tr.v[i].oid,path,0,out)<0){free(path);cvc_tree_free(&tr);return -1;}}else cvc_snapshot_add(out,path,tr.v[i].type,tr.v[i].oid);free(path);}cvc_tree_free(&tr);return 0;}
int cvc_snapshot_from_tree(const char*cvc,const uint8_t oid[32],CvcSnapshot*out){cvc_snapshot_init(out);if(load_tree_rec(cvc,oid,"",1,out)<0){cvc_snapshot_free(out);return -1;}cvc_snapshot_sort(out);return 0;}
int cvc_snapshot_from_commit(const char*cvc,const uint8_t oid[32],CvcSnapshot*out){CvcObjType t;CvcBuf p;if(cvc_object_read(cvc,oid,&t,&p)<0)return -1;if(t!=CVC_OBJ_COMMIT){cvc_buf_free(&p);return cvc_errorf("revision is not a commit");}CvcCommit c;if(cvc_commit_parse(p.data,p.len,&c)<0){cvc_buf_free(&p);return cvc_errorf("malformed commit");}cvc_buf_free(&p);int rc=cvc_snapshot_from_tree(cvc,c.root,out);cvc_commit_free(&c);return rc;}

static size_t comp_len(const char*p,size_t start){const char*s=strchr(p+start,'/');return s?(size_t)(s-(p+start)):strlen(p+start);}
static int write_tree_range(const char*cvc,const CvcSnapshot*s,size_t lo,size_t hi,size_t depth,uint8_t oid[32]){CvcBuf payload;cvc_buf_init(&payload);/* count child groups */uint32_t count=0;size_t i=lo;while(i<hi){size_t nl=comp_len(s->v[i].path,depth);count++;size_t j=i+1;while(j<hi&&comp_len(s->v[j].path,depth)==nl&&!memcmp(s->v[i].path+depth,s->v[j].path+depth,nl))j++;i=j;}cvc_put_u32be(&payload,count);i=lo;while(i<hi){size_t nl=comp_len(s->v[i].path,depth);size_t j=i+1;while(j<hi&&comp_len(s->v[j].path,depth)==nl&&!memcmp(s->v[i].path+depth,s->v[j].path+depth,nl))j++;const char*name=s->v[i].path+depth;int leaf=name[nl]==0;uint8_t cid[32],ty;if(leaf){if(j!=i+1){cvc_buf_free(&payload);return cvc_errorf("snapshot path prefix collision");}ty=s->v[i].type;memcpy(cid,s->v[i].oid,32);}else{for(size_t k=i;k<j;k++)if(s->v[k].path[depth+nl]!='/'){cvc_buf_free(&payload);return cvc_errorf("snapshot path collision");}ty=3;if(write_tree_range(cvc,s,i,j,depth+nl+1,cid)<0){cvc_buf_free(&payload);return -1;}}cvc_buf_putc(&payload,ty);cvc_put_u32be(&payload,(uint32_t)nl);cvc_buf_append(&payload,name,nl);cvc_buf_append(&payload,cid,32);i=j;}int rc=cvc_object_store(cvc,CVC_OBJ_TREE,payload.data,payload.len,oid);cvc_buf_free(&payload);return rc;}
int cvc_snapshot_write_tree(const char*cvc,const CvcSnapshot*s,uint8_t oid[32]){if(!s->n){unsigned char z[4]={0,0,0,0};return cvc_object_store(cvc,CVC_OBJ_TREE,z,4,oid);}return write_tree_range(cvc,s,0,s->n,0,oid);}
int cvc_snapshot_subtree(const CvcSnapshot*src,const char*root,CvcSnapshot*out){cvc_snapshot_init(out);size_t n=strlen(root);for(size_t i=0;i<src->n;i++){if(strcmp(src->v[i].path,root)==0||(!strncmp(src->v[i].path,root,n)&&src->v[i].path[n]=='/'))cvc_snapshot_add(out,src->v[i].path,src->v[i].type,src->v[i].oid);}cvc_snapshot_sort(out);return 0;}
